from __future__ import annotations

from ..performance import PerformanceMetric


def performance_budgets_markdown(metrics: tuple[PerformanceMetric, ...]) -> str:
    software = sum(metric.status == "enforced-software" for metric in metrics)
    physical = len(metrics) - software
    lines = [
        "# Performance Budgets",
        "",
        "> Generated by `./hfx generate`. Do not edit manually.",
        "",
        "This page lists the size, speed, and memory limits HyperFlux is held to, for",
        "contributors whose change might make it bigger or slower.",
        "",
        f"Checked by software tests: `{software}`. Need a hardware measurement: `{physical}`.",
        "The hardware limits are targets only. No hardware measurement is stored for any of them,",
        "so none blocks a release; each stays `unmeasured-physical` until a measurement is stored.",
        "No measurement history is stored; each software check compares the current value with its",
        "maximum.",
        "",
        "| Metric | Maximum | Measurement | Status | Release block |",
        "| --- | ---: | --- | --- | --- |",
    ]
    for metric in metrics:
        maximum = f"{metric.maximum:g} {metric.unit}"
        lines.append(
            f"| `{metric.id}` {metric.title} | {maximum} | `{metric.measurement_kind}` | "
            f"`{metric.status}` | {'yes' if metric.release_blocking else 'no'} |"
        )
    lines.extend(["", "## How Each Limit Is Measured", ""])
    for metric in metrics:
        lines.extend(
            [
                f"### {metric.title}",
                "",
                f"Source: [`{metric.source}`](../../{metric.source}); selector `{metric.selector}`.",
                f"Samples: {metric.sample_count}; warmups: {metric.warmup_count}.",
                "",
                metric.rationale,
                "",
            ]
        )
    return "\n".join(lines)
